	m.HandleFunc(http.MethodDelete+" "+options.BaseURL+"/api/grocery/lists/{id}/items/{itemId}", wrapper.DeleteItem)
	m.HandleFunc(http.MethodPatch+" "+options.BaseURL+"/api/grocery/lists/{id}/items/{itemId}", wrapper.UpdateItem)
